#!/bin/bash
# Generated by hpc-runner (SGE scheduler)

#$ -S /bin/bash
#$ -cwd
#$ -V
#$ -N sweep
#$ -pe smp 2
#$ -l h_vmem=4G
#$ -l h_rt=0:30:00
#$ -o /work/$JOB_NAME.$JOB_ID.out.$TASK_ID
#$ -j y
#$ -t 1-10:2%3
#$ -hold_jid 100,200,300

# Exit on error
set -e

# --- hpc-runner: publish this job's exit code (NFS-safe) ---
# SGE -hold_jid is afterany, so dependents read these sentinels to emulate
# afterok/afternotok. An array task publishes its own <JOB_ID>.<TASK>.rc.
# SGE sets SGE_TASK_ID=undefined for a non-array job, so treat that as unset.
# The EXIT trap fires on success, `set -e` failure, and the guard below, so
# the exit code is always published. Write-then-rename is atomic on NFS so a
# reader never sees a partial value.
_hpc_exit_dir=/shared/hpc-runner/exit
_hpc_task="${SGE_TASK_ID:-}"; [ "$_hpc_task" = undefined ] && _hpc_task=""; _hpc_rc_name="${JOB_ID}${_hpc_task:+.$_hpc_task}.rc"
mkdir -p "$_hpc_exit_dir"
_hpc_on_exit() {
    local _ec=$?
    { printf '%s\n' "$_ec" > "$_hpc_exit_dir/.${_hpc_rc_name}.$$" \
        && mv -f "$_hpc_exit_dir/.${_hpc_rc_name}.$$" "$_hpc_exit_dir/${_hpc_rc_name}" ; } 2>/dev/null || true
    if [ -n "${_hpc_modlog:-}" ]; then rm -f "$_hpc_modlog"; fi
    return "$_ec"
}
trap _hpc_on_exit EXIT

# --- hpc-runner environment ---
# Module system initialization
. /site/modules/init.sh
export MODULES_VERBOSITY=concise

# Module commands are quiet on success; their output is shown if one fails.
_hpc_modlog=$(mktemp)

# Purge modules for a clean environment
module purge 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module purge failed' >&2; exit 1; }

# Additional module paths
module use /site/modulefiles 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module use /site/modulefiles failed' >&2; exit 1; }

# Load modules
module load gcc/12 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module load gcc/12 failed' >&2; exit 1; }

# Unset environment variables
unset http_proxy
# --- end hpc-runner environment ---

# --- hpc-runner dependency guard: skip unless every dependency is satisfied ---
# -hold_jid guarantees parents have exited (and flushed their sentinels), but
# allow a short bounded wait for the NFS directory-entry cache to refresh.
_hpc_dep_rc() {
    local _rc="" _try
    for _try in $(seq 1 15); do
        if [ -f "$_hpc_exit_dir/$1" ]; then
            _rc="$(cat "$_hpc_exit_dir/$1" 2>/dev/null)"
            [ -n "$_rc" ] && break
        fi
        sleep 1
    done
    printf '%s' "$_rc"
}
_hpc_dep_skip() {
    echo "hpc-runner: $2 dependency $1 not satisfied (rc='${3:-missing}'); skipping" >&2
    exit 113
}
# afterok needs rc 0; afternotok needs a non-zero rc. A missing sentinel
# cannot prove the parent failed, so it fails both tests.
_hpc_dep_ok() {
    if [ "$1" = afterok ]; then
        [ "$2" = "0" ]
    else
        [ -n "$2" ] && [ "$2" != "0" ]
    fi
}
# A parent known only by id may be an array job: check <id>.rc, or, if that
# is absent after the bounded wait, every <id>.*.rc that exists (at least one
# is required). -hold_jid guarantees every task has exited and published, so
# the glob is complete.
_hpc_dep_check_id() {
    local _rc _f _found=""
    _rc="$(_hpc_dep_rc "$2.rc")"
    if [ -n "$_rc" ]; then
        _hpc_dep_ok "$1" "$_rc" || _hpc_dep_skip "$2.rc" "$1" "$_rc"
        return 0
    fi
    for _f in "$_hpc_exit_dir/$2".*.rc; do
        [ -f "$_f" ] || continue
        _found=1
        _rc="$(cat "$_f" 2>/dev/null)"
        _hpc_dep_ok "$1" "$_rc" || _hpc_dep_skip "${_f##*/}" "$1" "$_rc"
    done
    [ -n "$_found" ] || _hpc_dep_skip "$2.rc" "$1" ""
}
_hpc_dep_check_id afterok 100
for _s in 300.1.rc 300.2.rc 300.3.rc ; do
    _rc="$(_hpc_dep_rc "$_s")"
    _hpc_dep_ok afternotok "$_rc" || _hpc_dep_skip "$_s" afternotok "$_rc"
done

# Execute command
./sim.sh --seed $SGE_TASK_ID
_exit_code=$?


exit $_exit_code
